questions.question:
What is the output?
int a = 10, b = 3;
printf("%d %d", a / b, a % b);

What is the output?
char s[] = "hello";
printf("%zu %zu", sizeof(s), strlen(s));

What is the output?
int i = 2;
switch (i) {
  case 1: printf("A");
  case 2: printf("B");
  case 3: printf("C"); break;
  default: printf("D");
}

What is the output?
int i;
for (i = 0; i < 5; i++);
printf("%d", i);

What is the output?
int arr[5] = {1, 2};
printf("%d", arr[3]);

What is the output?
int n = 0;
do { n++; } while (n < 0);
printf("%d", n);

What is the output?
int a[] = {10, 20, 30};
int *p = a;
printf("%d", *(p + 2));

What is the output?
int x = 5;
int *p = &x;
int **q = &p;
**q = 10;
printf("%d", x);

What is the output?
void f(int n) { n = 20; }
int main() { int a = 10; f(a); printf("%d", a); }

What is the output?
void f() { static int c = 0; c++; printf("%d", c); }
int main() { f(); f(); f(); }

What is the output?
#define SQ(x) x*x
printf("%d", SQ(2+3));

What is the output?
char *s = "ABC";
printf("%c", *(s + 1));
